using System;using System.IO;using System.Text;using System.Collections.Generic;using System.Runtime.InteropServices;public class BrandTool{
[DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr BeginUpdateResource(string f,bool delete);[DllImport("kernel32.dll",SetLastError=true)]static extern bool UpdateResource(IntPtr h,IntPtr type,IntPtr name,ushort lang,byte[]data,uint size);[DllImport("kernel32.dll",SetLastError=true)]static extern bool EndUpdateResource(IntPtr h,bool discard);[DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern IntPtr LoadLibraryEx(string f,IntPtr h,uint flags);[DllImport("kernel32.dll")]static extern bool FreeLibrary(IntPtr h);delegate bool Names(IntPtr h,IntPtr t,IntPtr n,IntPtr p);delegate bool Langs(IntPtr h,IntPtr t,IntPtr n,ushort l,IntPtr p);[DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern bool EnumResourceNames(IntPtr h,IntPtr t,Names cb,IntPtr p);[DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern bool EnumResourceLanguages(IntPtr h,IntPtr t,IntPtr n,Langs cb,IntPtr p);[DllImport("kernel32.dll",CharSet=CharSet.Unicode,EntryPoint="UpdateResourceW")]static extern bool UpdateNamed(IntPtr h,IntPtr type,string name,ushort lang,byte[]data,uint size);
class Old{public int type;public IntPtr id;public string name;public ushort lang;}
static byte[] Block(string key,byte[]value,ushort type,ushort valueLen,params byte[][]children){using(var m=new MemoryStream())using(var w=new BinaryWriter(m,Encoding.Unicode)){w.Write((ushort)0);w.Write(valueLen);w.Write(type);w.Write(Encoding.Unicode.GetBytes(key+"\0"));while(m.Length%4!=0)w.Write((byte)0);w.Write(value);foreach(var child in children){while(m.Length%4!=0)w.Write((byte)0);w.Write(child);}byte[]b=m.ToArray();b[0]=(byte)b.Length;b[1]=(byte)(b.Length>>8);return b;}}
public static int Main(string[]a){try{var olds=new List<Old>();IntPtr lib=LoadLibraryEx(a[0],IntPtr.Zero,2);foreach(int type in new[]{3,14,16}){int capture=type;EnumResourceNames(lib,(IntPtr)type,(h,t,n,p)=>{string name=n.ToInt64()>65535?Marshal.PtrToStringUni(n):null;IntPtr id=name==null?n:Marshal.StringToHGlobalUni(name);EnumResourceLanguages(h,t,n,(hh,tt,nn,l,pp)=>{olds.Add(new Old{type=capture,id=id,name=name,lang=l});return true;},IntPtr.Zero);return true;},IntPtr.Zero);}FreeLibrary(lib);IntPtr update=BeginUpdateResource(a[0],false);if(update==IntPtr.Zero)throw new Exception("BeginUpdateResource failed");bool done=false;try{foreach(var old in olds){bool ok=old.name==null?UpdateResource(update,(IntPtr)old.type,old.id,old.lang,null,0):UpdateNamed(update,(IntPtr)old.type,old.name,old.lang,null,0);if(!ok)throw new Exception("Remove resource failed");}byte[]ico=File.ReadAllBytes(a[1]);int count=BitConverter.ToUInt16(ico,4);using(var m=new MemoryStream())using(var w=new BinaryWriter(m)){w.Write((ushort)0);w.Write((ushort)1);w.Write((ushort)count);for(int i=0;i<count;i++){int p=6+i*16,size=BitConverter.ToInt32(ico,p+8),offset=BitConverter.ToInt32(ico,p+12);byte[]img=new byte[size];Buffer.BlockCopy(ico,offset,img,0,size);if(!UpdateResource(update,(IntPtr)3,(IntPtr)(i+1),1033,img,(uint)size))throw new Exception("Icon update failed");w.Write(ico,p,12);w.Write((ushort)(i+1));}byte[]group=m.ToArray();if(!UpdateResource(update,(IntPtr)14,(IntPtr)1,1033,group,(uint)group.Length))throw new Exception("Icon group failed");}
var strings=new List<byte[]>();var pairs=new Dictionary<string,string>{{"CompanyName","Daemon"},{"FileDescription","Daemon M2 Tool"},{"FileVersion",a[2]},{"InternalName","Daemon M2 Tool"},{"OriginalFilename","Daemon Viewer.exe"},{"ProductName","Daemon M2 Tool"},{"ProductVersion",a[2]},{"LegalCopyright","by Daemon"}};foreach(var pair in pairs){byte[]v=Encoding.Unicode.GetBytes(pair.Value+"\0");strings.Add(Block(pair.Key,v,1,(ushort)(v.Length/2)));}byte[]table=Block("040904b0",new byte[0],1,0,strings.ToArray()),info=Block("StringFileInfo",new byte[0],1,0,table),translation=Block("Translation",new byte[]{9,4,176,4},0,4),vars=Block("VarFileInfo",new byte[0],1,0,translation);Version ver=new Version(a[2]);using(var mm=new MemoryStream())using(var ww=new BinaryWriter(mm)){uint ms=(uint)((ver.Major<<16)|ver.Minor),ls=(uint)(ver.Build<<16);foreach(uint n in new uint[]{0xfeef04bd,0x10000,ms,ls,ms,ls,0x3f,0,0x40004,1,0,0,0})ww.Write(n);byte[]version=Block("VS_VERSION_INFO",mm.ToArray(),0,52,info,vars);if(!UpdateResource(update,(IntPtr)16,(IntPtr)1,1033,version,(uint)version.Length))throw new Exception("Version failed");}if(!EndUpdateResource(update,false))throw new Exception("Commit resources failed");done=true;}finally{if(!done)EndUpdateResource(update,true);}Console.WriteLine("Branding complete");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
